m=np.arange(1,61);B0=100e6;r=.06/12;A=B0*r/(1-(1+r)**-360);bal=B0*(1+r)**m-A*((1+r)**m-1)/r;prev=np.r_[B0,bal[:-1]];inte=(.06-.0025)/12*prev;prin=A-r*prev;ax.bar(m,inte/1e6,label='Net interest',color=ACCENT);ax.bar(m,prin/1e6,bottom=inte/1e6,label='Scheduled principal',color=GOOD);ax.set_xlabel('Month');ax.set_ylabel('Cash flow (USD M)');ax.set_title('First five years of a $100M pass-through',loc='left');ax.legend(fontsize=8)
